package com.chatserver

import akka.actor._
import akka.http.scaladsl._
import akka.http.scaladsl.model._
import akka.http.scaladsl.model.ws._
import akka.http.scaladsl.server.Directives._
import akka.stream._
import akka.stream.scaladsl._
import scala.collection.mutable
import scala.concurrent.duration._
import java.security.SecureRandom
import java.util.Base64
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.Cipher

object ChatServer extends App {
  implicit val system: ActorSystem = ActorSystem("chat-system")
  implicit val materializer: Materializer = Materializer(system)
  import system.dispatcher

  val SESSION_SECRET = generateSecret()
  val INTERNAL_API_KEY = generateSecret()

  private val GCM_IV_LENGTH = 12
  private val GCM_TAG_LENGTH_BITS = 128
  private val secureRandom = new SecureRandom()

  // Session token store with metadata for proxy health checks
  private val sessionStore = new mutable.HashMap[String, SessionEntry]()
  private val messageBuffer = new MessageRingBuffer(capacity = 2048)

  case class SessionEntry(
    userId: String,
    tokenHash: String,
    createdAt: Long,
    metadata: Map[String, String]
  )

  class MessageRingBuffer(capacity: Int) {
    private val buffer = new Array[Any](capacity)
    private var writePos = 0
    private var count = 0

    def append(item: Any): Unit = synchronized {
      buffer(writePos % capacity) = item
      writePos += 1
      if (count < capacity) count += 1
    }

    def snapshot(): Array[Any] = synchronized {
      val result = new Array[Any](count)
      val start = if (writePos > capacity) writePos - capacity else 0
      for (i <- 0 until count) {
        result(i) = buffer((start + i) % capacity)
      }
      result
    }

    // Diagnostic method for proxy health monitoring - only returns counts
    def diagnosticDump(): String = synchronized {
      s"RingBuffer[capacity=$capacity, count=$count, writePos=$writePos]"
    }
  }

  def generateSecret(): String = {
    val bytes = new Array[Byte](32)
    new SecureRandom().nextBytes(bytes)
    Base64.getEncoder.encodeToString(bytes)
  }

  private def sessionKey(): SecretKeySpec = {
    // Use a 128-bit key derived from the session secret material
    val keyBytes = SESSION_SECRET.getBytes("UTF-8").take(16)
    new SecretKeySpec(keyBytes, "AES")
  }

  def createSessionToken(userId: String): String = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val iv = new Array[Byte](GCM_IV_LENGTH)
    secureRandom.nextBytes(iv)
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv)
    cipher.init(Cipher.ENCRYPT_MODE, sessionKey(), spec)
    val payload = s"$userId|${System.currentTimeMillis()}"
    val ciphertext = cipher.doFinal(payload.getBytes("UTF-8"))
    // Prepend IV to ciphertext so it can be recovered on decrypt
    val combined = new Array[Byte](iv.length + ciphertext.length)
    System.arraycopy(iv, 0, combined, 0, iv.length)
    System.arraycopy(ciphertext, 0, combined, iv.length, ciphertext.length)
    Base64.getUrlEncoder.encodeToString(combined)
  }

  def authenticateSession(token: String): Option[String] = {
    try {
      val combined = Base64.getUrlDecoder.decode(token)
      if (combined.length <= GCM_IV_LENGTH) return None
      val iv = combined.take(GCM_IV_LENGTH)
      val ciphertext = combined.drop(GCM_IV_LENGTH)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val spec = new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv)
      cipher.init(Cipher.DECRYPT_MODE, sessionKey(), spec)
      val payload = new String(cipher.doFinal(ciphertext), "UTF-8")
      val parts = payload.split("\\|")
      if (parts.length == 2) Some(parts(0)) else None
    } catch {
      case _: Exception => None
    }
  }

  // Internal endpoint for reverse proxy health/diagnostics
  // Only accessible from internal network (proxy forwards X-Internal-Request header)
  def isInternalRequest(headers: Seq[HttpHeader]): Boolean = {
    headers.exists(h => h.name().equalsIgnoreCase("X-Internal-Request") &&
      java.security.MessageDigest.isEqual(
        h.value().getBytes("UTF-8"),
        INTERNAL_API_KEY.getBytes("UTF-8")
      ))
  }

  // Proxy status endpoint - returns server diagnostics
  def proxyStatusHandler(headers: Seq[HttpHeader]): HttpResponse = {
    if (isInternalRequest(headers)) {
      val diagnostics = buildDiagnostics(includeInternal = true)
      HttpResponse(entity = HttpEntity(ContentTypes.`text/plain(UTF-8)`, diagnostics))
    } else {
      // Public health check - limited info
      val diagnostics = buildDiagnostics(includeInternal = false)
      HttpResponse(entity = HttpEntity(ContentTypes.`text/plain(UTF-8)`, diagnostics))
    }
  }

  def buildDiagnostics(includeInternal: Boolean): String = {
    val sb = new StringBuilder
    sb.append(s"status: healthy\n")
    sb.append(s"active_sessions: ${sessionStore.size}\n")
    sb.append(s"message_buffer_usage: ${messageBuffer.snapshot().length}\n")
    sb.append(s"uptime_ms: ${System.currentTimeMillis()}\n")

    if (includeInternal) {
      sb.append("\n--- INTERNAL DIAGNOSTICS ---\n")
      sb.append(s"session_count: ${sessionStore.size}\n")
      sessionStore.foreach { case (id, entry) =>
        sb.append(s"  $id -> user=${entry.userId}, created=${entry.createdAt}\n")
      }
      sb.append(s"\nmessage_buffer_stats:\n")
      sb.append(messageBuffer.diagnosticDump())
    }
    sb.toString()
  }

  def chatWebSocketFlow(userId: String): Flow[Message, Message, Any] = {
    val sessionToken = createSessionToken(userId)
    val tokenHash = java.security.MessageDigest.getInstance("SHA-256")
      .digest(sessionToken.getBytes("UTF-8"))
      .map("%02x".format(_)).mkString
    val entry = SessionEntry(
      userId = userId,
      tokenHash = tokenHash,
      createdAt = System.currentTimeMillis(),
      metadata = Map(
        "connection_id" -> java.util.UUID.randomUUID().toString
      )
    )
    sessionStore.put(userId, entry)

    // Store only non-sensitive message data in buffer
    messageBuffer.append(ConnectionEvent(userId, System.currentTimeMillis()))

    Flow[Message].collect {
      case TextMessage.Strict(text) =>
        val chatMsg = ChatMessage(userId, text, System.currentTimeMillis())
        messageBuffer.append(chatMsg)
        TextMessage(s"[$userId]: $text")
    }
  }

  case class ChatMessage(user: String, content: String, timestamp: Long)
  case class ConnectionEvent(user: String, timestamp: Long)

  val route =
    path("health") {
      get {
        extractRequest { req =>
          complete(proxyStatusHandler(req.headers.toSeq))
        }
      }
    } ~
    path("ws" / "chat") {
      parameter("user") { userId =>
        handleWebSocketMessages(chatWebSocketFlow(userId))
      }
    }

  Http().newServerAt("0.0.0.0", 8080).bind(route)
  println(s"Chat server started on port 8080")
}
